const migrateStoredData=(stored:Record<string,Row[]>,sheets:Sheet[],plantType:PlantType):Record<string,Row[]>=>{
 const next={...stored}
 for(const sheet of sheets){
  const old=stored[sheet.id]
  if(!old)continue
  const template=makeRows(sheet,plantType),templateLabels=new Set(template.map(row=>row.label))
  const projectAliases:Record<string,string>={'وام بانک ملی هامبورگ ۱':'بانک ملی هامبورگ — ارزی','وام بانک ملی هامبورگ ۲':'بانک ملی هامبورگ — ریالی (معادل ارز)','وام بانک تجارت ۱':'بانک تجارت — ارزی'}
  const merged=template.map(row=>{const previous=old.find(x=>x.label===row.label)??(sheet.id==='project'&&projectAliases[row.label]?old.find(x=>x.label===projectAliases[row.label]):undefined);if(!previous)return row;const values={...row.values,...previous.values};if(sheet.id==='reference-reconciliation'&&row.label==='جریان نقدی واقعی reference (خالص پروژه)'&&Array.from({length:19},(_,i)=>values['y'+(i+1)]).every(value=>value===undefined||value===''))referenceReferenceCashFlows.forEach((value,index)=>values['y'+(index+1)]=value);if(sheet.id==='energy'&&plantType==='steelmaking'){const fixes:Record<string,[number,number]>={'آب صنعتی':[1.4,2.5],'آب شرب — مترمکعب بر ساعت':[6,12],'اکسیژن گازی':[15,40],'گاز صنعتی':[250,20]};const fix=fixes[row.label];if(fix&&Number(values.specific)===fix[0])values.specific=fix[1]}if(sheet.id==='materials'&&plantType==='steelmaking'&&row.label==='آهک پخته'&&Number(values.specific)===2)values.specific=64;if(sheet.id==='sales'&&plantType==='steelmaking'){if(Number(values.price)===660)values.price=680;if(Number(values.price)===640)values.price=650}if(['land','site','buildings','vehicles','infrastructure','office','preop','staff'].includes(sheet.id)&&values.allocation===50)values.allocation=100;if(sheet.id==='machines'&&values.sharedAllocation===50)values.sharedAllocation=100;if(sheet.id==='buildings')values.sharedFactor=0;if(sheet.id==='inflow'||sheet.id==='loans')for(let i=1;i<=9;i++)values['p'+i]=previous.values['y'+i]??previous.values['p'+i]??0;return{...row,id:previous.id,values}})
  const extras=sheet.book==='finance'&&sheet.id!=='project'?[]:old.filter(row=>!templateLabels.has(row.label)&&!(sheet.id==='machines'&&row.label.startsWith('سازه'))&&!Object.values(projectAliases).includes(row.label))
  next[sheet.id]=[...merged,...extras]
 }
 if(!stored.machineStructures){
  const oldMachines=stored.machines??[]
  next.machineStructures=makeStructureRows().map(row=>{const previous=oldMachines.find(x=>(x.label.startsWith('سازه:')?x.label.slice(6).trim():x.label)===row.label);if(!previous)return row;return{...row,values:{...row.values,length:previous.values.structureLength??row.values.length,width:previous.values.structureWidth??row.values.width,craneLevel:previous.values.craneLevel??row.values.craneLevel,steelStructure:previous.values.steelStructure??row.values.steelStructure,roofing:previous.values.roofing??row.values.roofing,cladding:previous.values.cladding??row.values.cladding,steelWeight:previous.values.steelWeight??row.values.steelWeight,price:previous.values.structurePrice??row.values.price}}})
 }
 return next
}
